import{_ as a,o as i,c as n,ai as l}from"./chunks/framework.Ai2o9gNv.js";const g=JSON.parse('{"title":"10-布尔类型","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/10-布尔类型/10-布尔类型.md","filePath":"仓颉入门到实战/10-布尔类型/10-布尔类型.md","lastUpdated":1734480750000,"__rawMarkdown":"# 10-布尔类型\\n\\n布尔类型使用 `Bool` 表示，用来表示逻辑中的真和假。\\n\\n## 布尔类型字面量\\n\\n布尔类型只有两个字面量：`true` 和 `false`。\\n\\n下面的例子展示了布尔字面量的使用：\\n\\n```javascript\\nlet a: Bool = true;\\nlet b: Bool = false;\\n```\\n\\n## 布尔类型支持的操作\\n\\n布尔类型支持的操作符包括：逻辑操作符（逻辑非 `!`，逻辑与 `&&`，逻辑或 `||`）、部分关系操作符（`==` 和 `!=`）、赋值操作符、部分复合赋值操作符（`&&=` 和 `||=`）。\\n\\n```javascript\\npackage pro\\n\\nmain() {\\n    let a = true\\n    // 逻辑非   表示取反\\n    let b = !a //  false\\n\\n    // 逻辑与\\n    // let c = !b && a // true    要求 所有条件都满足  结果为 true\\n    //  逻辑或\\n    let d = a || b // true // 有一个为真， 结果为 true\\n\\n    // ==  是否相等\\n    let e = 100 == 200 // false  因为 100 不等于 200\\n\\n    // !=  是否 不等\\n    let f = 100 != 200 // true  因为 100 不等于 200\\n\\n    // &&=\\n    var g = false\\n\\n    g &&= true // g = false    因为 当g等于false，&&= 右边的true不会执行\\n\\n    var h = true\\n    h &&= false // h = false  因为当h = true时，&&= 右边的true会执行\\n\\n    // ||=\\n    var i = true\\n    i ||= false // i = true ， 因为当i等于true时，||= 右边的false不会执行\\n\\n    var j = false\\n    j ||= true // j = true , 因为当j=等于false，||= 右边的true会执行\\n}\\n\\n```\\n\\n**需要注意的是，当出现未被使用的变量时，程序在编译时会出现警告**\\n\\n```javascript\\n let e = 100 == 200 // false  因为 100 不等于 200\\n  ^ unused variable\\n  # note: this warning can be suppressed by setting the compiler option `-Woff unused`\\n```\\n"}'),e={name:"仓颉入门到实战/10-布尔类型/10-布尔类型.md"};function p(t,s,h,k,r,d){return i(),n("div",null,[...s[0]||(s[0]=[l("",11)])])}const u=a(e,[["render",p]]);export{g as __pageData,u as default};
